import json,hashlib
from pathlib import Path
root=Path(__file__).resolve().parents[2]; audit=root/'Examtopics/audit'
text=(root/'CCNA-App/app/src/main/assets/data/ccna_cards_data.js').read_text(encoding='utf-8');qs=json.loads(text[text.index('['):].strip().rstrip(';'));by={q['id']:q for q in qs}
explanations={
1191:'''IPv4 /19 划分 64 个等长子网需借 6 位，得到 /25。第二个子网为 10.30.64.128/25，可用范围 10.30.64.129–10.30.64.254；分别配置至 Sw101 和 Sw102 的 e0/0。IPv6 /56 划分 64 个等长子网得到 /62，第二个是 2001:db8:0:4::/62；以下两地址的低 64 位互异。若使用 /64 EUI-64 则只使用该 /62 的四分之一，不符合最大化子网空间的条件；IID 唯一性应核查。二者须为支持三层接口的平台并启用相应接口功能。\n\n```text\nSw101(config)# interface ethernet 0/0\nSw101(config-if)# ip address 10.30.64.129 255.255.255.128\nSw101(config-if)# ipv6 address 2001:db8:0:4::1/62\nSw101(config-if)# no shutdown\nSw102(config)# interface ethernet 0/0\nSw102(config-if)# ip address 10.30.64.254 255.255.255.128\nSw102(config-if)# ipv6 address 2001:db8:0:4::2/62\nSw102(config-if)# no shutdown\n```\n\n用 show ip interface brief、show ipv6 interface brief 和双向 ping 验证；按实验要求保存配置。''',
1192:'''图中 R1 经 R2 和 R3 均可向 R4 的 2001:db8:41::/64 转发，但图仅标出链路前缀，未给每个路由器接口的完整 IPv6 地址；应以实际接口输出确定下一跳，不应把 ::2 或 ::3 当作图中已确认的地址。示例框架：\n\n```text\nipv6 unicast-routing\nipv6 route 2001:db8:41::/64 <R2直连接口地址>\nipv6 route 2001:db8:41::/64 <R3直连接口地址> 10\nshow ipv6 route 2001:db8:41::/64\n```\n\n默认静态路由管理距离为 1，备份 10 更高；R2/R3 到目的网段及回程必须已有可达路由。连接物理 down 时主路由通常失效；若只是远端故障而下一跳仍可递归到达，则需要其他跟踪机制。使用图中 Server1 地址 2001:db8:41::10 验证 ping 和 traceroute；实验完成后恢复接口并保存。原题图误放了上一题解答，现将对应拓扑移到题干。''',
1193:'''图示 SW-1 e0/1 连接电话及 PC1：PC1 VLAN 10、电话 VLAN 11；SW-2 e0/1 连接 VLAN 30 的 PC2。SW-1 与 SW-2 的互联口均是 e0/0，SW-1 接 R1 为 e0/2。原解析误用 voice VLAN 20、PC2 VLAN 10 并颠倒互联接口。\n\n```text\nSW-1(config)# vlan 10\nSW-1(config-vlan)# name Engineering\nSW-1(config)# interface e0/1\nSW-1(config-if)# switchport mode access\nSW-1(config-if)# switchport access vlan 10\nSW-1(config-if)# switchport voice vlan 11\nSW-1(config)# lldp run\nSW-1(config)# interface e0/0\nSW-1(config-if)# lldp transmit\nSW-1(config-if)# lldp receive\nSW-1(config)# interface e0/2\nSW-1(config-if)# no cdp enable\nSW-2(config)# interface e0/1\nSW-2(config-if)# switchport mode access\nSW-2(config-if)# switchport access vlan 30\nSW-2(config)# lldp run\nSW-2(config)# interface e0/0\nSW-2(config-if)# lldp transmit\nSW-2(config-if)# lldp receive\n```\n\n确认 VLAN 11 和 30 存在、互联 trunk 放行所需 VLAN，并核验 R1 三层网关及回程；图仅明确 R1 的 VLAN 10/30 地址，电话 VLAN 的网关需现场确认。接口命令 no cdp enable 控制该接口 CDP 邻居发现，不是过滤所有 Cisco 协议。用 show lldp neighbors、show interfaces switchport 等核验并保存。''',
1194:'''拓扑表给出数据 VLAN 77、名称 User_VLAN；语音 VLAN 177、名称 Voice_VLAN。两台交换机的 e0/1–e0/3 连接电话及 PC，e0/0 为互联接口。原解析的 VLAN 10/20 不符。两台均执行：\n\n```text\nvlan 77\n name User_VLAN\nvlan 177\n name Voice_VLAN\ninterface range e0/1 - 3\n switchport mode access\n switchport access vlan 77\n switchport voice vlan 177\n spanning-tree portfast\nlldp run\ninterface e0/0\n lldp transmit\n lldp receive\n```\n\n检查 e0/0 的二层连接及两 VLAN 允许列表；如果需要跨交换机同时承载两 VLAN，应保证两端 trunk 配置兼容。用 show vlan、show interfaces switchport、show lldp neighbors 验证；保存配置。''',
1195:'''拓扑将 SW-1 与 SW-2 的 e0/0、e0/1 聚合为 Po12；两端均采用主动 LACP，聚合 trunk 允许 VLAN 1,12,22。SW-1 e0/2 独立 trunk 仅允许 12,22。按平台支持决定是否需要或允许 dot1q 封装命令；确认已有端口配置和聚合兼容后，两端分别执行：\n\n```text\ninterface range e0/0 - 1\n channel-group 12 mode active\ninterface port-channel 12\n switchport mode trunk\n switchport trunk allowed vlan 1,12,22\n```\n\nSW-1 另执行：\n```text\ninterface e0/2\n switchport mode trunk\n switchport trunk allowed vlan 12,22\n```\n\n检查 VLAN 存在、对端 trunk/聚合设置一致及 STP 状态；使用 show etherchannel summary 和 show interfaces trunk 验证，必要时按实验平台补充 encapsulation dot1q。原展示图为上一题解答，现改为对应拓扑。''',
1196:'''拓扑给出 PC1 172.16.10.10、PC2 172.16.20.10，R1 172.16.30.2。Vigenère 题意对应 IOS service password-encryption 的可逆 type 7，不是 secret 哈希；Exec mode 使用普通 privilege 1。示例：\n\n```text\n! Sw101\nservice password-encryption\nusername netops privilege 1 password 0 ipsec4all\nline vty 0 4\n login local\n transport input telnet\n! Sw103：仅当此交换机实际路由 VLAN 10 且入口是 SVI 时\nip access-list extended ENT_ACL\n deny icmp host 172.16.10.10 host 172.16.20.10 echo\n permit tcp host 172.16.10.10 host 172.16.30.2 eq telnet\n deny tcp 172.16.10.0 0.0.0.255 any eq telnet\n permit ip any any\ninterface vlan 10\n ip access-group ENT_ACL in\n! Sw102\ninterface e0/0\n switchport mode access\n switchport port-security\n switchport port-security maximum 2\n switchport port-security violation restrict\n```\n\nACL 顺序允许指定 Telnet 后拒绝 VLAN 10 其他 Telnet，最后放行其他 IP；先确认 VLAN 10 的子网掩码为 /24、Sw103 是三层入口，否则按实际网段/经过的三层接口调整。port-security 默认支持动态学习，无需 sticky；restrict 丢弃违规帧并计数、发出通知，具体日志依平台配置。type 7 及 Telnet 安全性有限，但这里按题设练习。验证 ACL 命中、VTY 和端口安全并保存。''',
1197:'''图中 R2 e0/1 朝 R3、e0/0 朝 R1；R3 e0/1 为 10.2.3.3，R3 Loopback1 为 192.168.3.1，e0/2 当前标示 10.1.3.11。源选择及实际路由决定 NAT ACL 应匹配哪些 R3 源地址；R3 到 R1 还有直连路径，测试 NAT 须确保流量实际经过 R2。示例（按图中已知源限定，按实际需要增补）：\n\n```text\n! R2\nip access-list standard XLATE\n permit host 10.2.3.3\n permit host 192.168.3.1\n permit host 10.1.3.11\nip nat pool test_pool 10.10.10.1 10.10.10.254 prefix-length 24\nip nat inside source list XLATE pool test_pool\ninterface e0/1\n ip nat inside\ninterface e0/0\n ip nat outside\nntp server 10.1.2.1\n! R3\ninterface e0/2\n ip address dhcp\n no shutdown\nip domain-name example.net\nusername root secret s3cret\ncrypto key generate rsa modulus 2048\nip ssh version 2\nline vty 0 4\n login local\n transport input ssh\n! R1，如需以自身时钟提供时间\nntp master 2\n```\n\nDHCP 可能改变 R3 e0/2 的源地址，须同步核查 NAT ACL、SSH 目的地址和回程；地址池需确保唯一且 R1 有池地址回程路由。通过指定源 ping 和 show ip nat translations 验证 NAT，show ntp associations 验证 NTP，从 R1 对 R3 的 DHCP 地址执行 ssh -l root；实际 VTY 范围与平台能力应核对。''',
1198:'''拓扑显示三个 PC 均连接各自交换机 e0/2：PC1、PC3 是 VLAN 99，PC2 使用默认 VLAN（通常为 1）。三台交换机创建 VLAN 99 并命名 FINANCIAL；仅 PC1/PC3 接入口属于 VLAN 99，PC2 需使用实际默认 VLAN。SW-1 全局启用 Cisco CDP，同时在连接 PC1 的 e0/2 关闭 CDP。\n\n```text\n! SW-1、SW-2、SW-3 均配置\nvlan 99\n name FINANCIAL\ninterface e0/2\n switchport mode access\n! SW-1 和 SW-3 的 e0/2\n switchport access vlan 99\n! SW-2 的 e0/2，图示默认 VLAN 1\n switchport access vlan 1\n! 仅 SW-1\ncdp run\ninterface e0/2\n no cdp enable\n```\n\n按拓扑检查互联 trunk 允许对应 VLAN，且 VLAN 99 跨链路可达；以 show cdp、show cdp interface、show vlan 和 show interfaces trunk 验证。如果题意要求阻止其他发现协议，需另行检查 LLDP；原解析只关闭 LLDP 且把 PC2 错放 VLAN99，不能满足题意。保存配置。''',
1199:'''图中 R1、R2 e0/0 直连，IPv4 为 10.0.12.4/30，两个可用主机地址是 .5 和 .6；IPv6 为 2001:db8:12::/126，包含 ::0–::3，排除题设 subnet-router anycast 全零后，首个为 ::1、最后一个为 ::3。IPv6 没有广播地址，不能照搬 IPv4 的最后一地址不可用规则。\n\n```text\n! R1\ninterface e0/0\n ip address 10.0.12.5 255.255.255.252\n ipv6 address 2001:db8:12::1/126\n no shutdown\n! R2\ninterface e0/0\n ip address 10.0.12.6 255.255.255.252\n ipv6 address 2001:db8:12::3/126\n no shutdown\n```\n\n检查各接口运行状态并双向 ping 10.0.12.5/.6 和 IPv6 ::1/::3；按要求保存配置。原解析采用未经题图支持的网段，且未配置 IPv6 最后地址。''',
1200:'''图示 R5 与 R1 共用 10.100.110.0/25，R1 地址为 10.100.110.1；R1→R3 的下一跳为 10.133.13.3，R1→R2 的下一跳为 10.122.12.2，R2→R1 为 10.122.12.1。R6 地址为 10.200.220.6。按题设：\n\n```text\n! R5\nip route 10.200.220.6 255.255.255.255 10.100.110.1\n! R1\nip route 0.0.0.0 0.0.0.0 10.133.13.3\nip route 0.0.0.0 0.0.0.0 10.122.12.2 225\n! R2\nip route 10.100.110.0 255.255.255.128 10.122.12.1\n```\n\n确认其他设备已有目的和回程路径。R5 用 ping/traceroute 至 10.200.220.6；按实验指示关闭 R1 e0/1，检查路由表由 R3 主路由切换至 AD 225 的 R2 备份，再重复测试。链路恢复后恢复实验接口并保存。浮动静态路由只在主路由不再有效时入表；远端故障不一定会令直连下一跳失效。原解析错误写成经 R4、AD 10 且漏配 R2 回程。'''
}
corrections=[];reviews=[]
for n in range(1191,1201):
 q=by[n];updates={'explanation':explanations[n]}
 if n != 1193: updates.update(image=q['answer_image'],answer_image=None)
 else: updates['answer_image']=None
 fp=hashlib.sha256(json.dumps(q,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()
 corrections.append(dict(id=n,before_sha256=fp,updates=updates,reason='核对题目、实验拓扑与图文错位，修复错误解答；保留原图证据。'))
 reviews.append(dict(id=n,content_answer_explanation='逐题核对实验需求、图中地址/接口及 CLI；答案为实验步骤，无拖拽题。',image_code='直接查看现有题图及答案图；修复错位拓扑、CLI 与解析。',source_urls=['https://www.rfc-editor.org/rfc/rfc4291','https://www.cisco.com/c/en/us/support/docs/ip/network-address-translation-nat/13772-12.html']))
(audit/'agent-1191-1200.json').write_text(json.dumps(dict(scope='Q1191–Q1200',corrections=corrections,reviews=reviews,images_directly_viewed=[f'exhibits/q{n}_answer_image_1191.png' for n in range(1191,1201)],limitations='图片和地址计算检查，未进行设备实验。'),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(audit/'agent-1191-1200.md').write_text('# Q1191–Q1200 逐题审查\n\n全部为实验题，无拖拽分组。逐题检查题干、现有原图、答案图与解析；其中 Q1191、1192、1194–1200 的拓扑在答案图位置，已移到题干，Q1193 原题图保留。原图证据存放 exhibits/q1191...q1200。\n\n'+''.join(f'- Q{n}：{explanations[n].splitlines()[0][:220]}\n' for n in range(1191,1201))+'\n设备及 CLI 未实测；可用接口、设备路由和配置需现场核对。\n',encoding='utf-8')
print('prepared 10 corrections')
